// Analytics service helpers.
//
// These functions perform side effects (e.g. posting to an analytics
// endpoint) and are meant to be called from `after()` so they run after
// the response has been sent without blocking it.

export interface PageViewEvent {
  path: string
  userAgent: string
  timestamp: string
}

export async function logPageView(event: PageViewEvent): Promise<void> {
  const url = process.env.ANALYTICS_ENDPOINT

  // When no endpoint is configured, fall back to a no-op log so this works
  // in any environment without throwing.
  if (!url) {
    console.log('[analytics] page view:', event)
    return
  }

  await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event),
    // `keepalive` lets the request outlive the request lifecycle, which
    // pairs well with `after()` on serverless runtimes.
    keepalive: true,
  })
}

