import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/utils'

export default async function Home() {
  // Read request data *before* `after`. In a Server Component, request-time
  // APIs like `headers()` cannot be called inside the `after` callback, so
  // we capture the values during render and pass them in via closure.
  const userAgent = (await headers()).get('user-agent') || 'unknown'

  // Schedule the analytics call to run after the response is sent to the
  // user, so logging never blocks the page from rendering.
  after(() => {
    logPageView({
      path: '/',
      userAgent,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by — your visit has been noted.</p>
    </main>
  )
}

